import csv, collections
E='42493d5e-d7c8-5e7c-b100-a81e5d773b79'
O='26776421-83f2-518b-9716-873fcaa13a04'
elec=collections.defaultdict(list)
occ=collections.defaultdict(list)
with open(VALUES_CSV, encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        tid=row['timeseries_id']
        if tid==E:
            elec[row['timestamp']].append(float(row['value']))
        elif tid==O:
            occ[row['timestamp']].append(float(row['value']))
# only 2018-07-23
date='2018-07-23'
elec_d={k:v for k,v in elec.items() if k.startswith(date)}
occ_d={k:v for k,v in occ.items() if k.startswith(date)}
print('electric hours:',len(elec_d),'occ hours:',len(occ_d))
count=0
for ts,v in elec_d.items():
    pv=sum(v)/len(v)
    if ts in occ_d:
        ov=sum(occ_d[ts])/len(occ_d[ts])
        if pv>1 and ov==0:
            count+=1
print(count)
